import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
import {journalLines} from '../live-paper/journal-lines.mjs';import {amount,money} from '../paper/fixed.mjs';import {auditPassiveOpportunities} from '../live-paper/passive-opportunity-audit.mjs';
import {replayJournal} from '../execution/ledger.mjs';
const verifyExisting=process.argv.includes('--verify-existing'),existing=verifyExisting?JSON.parse(fs.readFileSync('data/fill-economics-audit-20261005.json')):null;
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),sha=b=>createHash('sha256').update(b).digest('hex');
function verified(file,through=null){let seq=0,previous='',bytes=0,last=null;const h=createHash('sha256'),rows=[];
 for(const line of journalLines(file)){const r=JSON.parse(line),{hash,...body}=r;assert.equal(r.sequence,++seq);assert.equal(r.previous,previous);assert.equal(hash,sha(JSON.stringify(body)));previous=hash;h.update(line+'\n');bytes+=Buffer.byteLength(line)+1;last=r;rows.push(r);if(seq===through)break;}
 if(through!==null)assert.equal(seq,through);return{rows,last,proof:{bytes,sha256:h.digest('hex'),sequence:seq,tailHash:previous}};
}
const passive=verified(path.join(rt,'stable-maker-cohorts','baal-stable-spread-20261005-v2-live','journal.jsonl'),existing?.sourceProof.passive.sequence??null),state=passive.last.state;
const tape=verified(path.join(rt,'anonymous-trades.jsonl'),state.tapeSequence);assert.equal(tape.last.hash,state.tapeHash);
const quotes=Object.values(state.paper.wallets).flatMap(w=>Object.values(w.quotes)),opportunities=auditPassiveOpportunities(quotes,tape.rows.map(r=>r.event));
const core=verified(path.join(rt,'competition','core-journal.jsonl'),existing?.sourceProof.officialCore.sequence??null),intents=Object.values(core.last.state.intents).sort((a,b)=>Date.parse(a.preparedAt)-Date.parse(b.preparedAt)),inventory=new Map(),markets=new Map();let actualFills=0,atLimit=0,priceImproved=0;
const ledgerBytes=fs.readFileSync(path.join(rt,'competition','execution-journal.jsonl')),ledger=replayJournal(ledgerBytes.toString('utf8'));
for(const i of intents){const attributed=ledger.intents[i.intentId];assert.equal(attributed.attribution.ownerId,'Codex');assert.equal(String(attributed.orderId),String(i.orderId));assert.equal(attributed.attribution.marketId,i.marketId);assert.equal(i.acceptanceUncertain,false);assert.equal(i.status,'closed');let filled=0;
 for(const f of i.reconciledFills){actualFills++;filled+=f.quantity;assert(f.quantity>0);const px=amount(f.price),limit=amount(i.price);assert(i.action==='buy'?px<=limit:px>=limit);if(px===limit)atLimit++;else priceImproved++;
  const m=markets.get(i.marketId)||{marketId:i.marketId,buyShares:0,sellShares:0,buyCost:0n,sellProceeds:0n,realized:0n};markets.set(i.marketId,m);const fifo=inventory.get(i.exchangeId)||[];inventory.set(i.exchangeId,fifo);
  if(i.action==='buy'){fifo.push({quantity:f.quantity,price:px});m.buyShares+=f.quantity;m.buyCost+=BigInt(f.quantity)*px;}else{m.sellShares+=f.quantity;m.sellProceeds+=BigInt(f.quantity)*px;let remaining=f.quantity;while(remaining){assert(fifo.length,'Unattributed sell cannot be adopted');const lot=fifo[0],n=Math.min(remaining,lot.quantity);m.realized+=BigInt(n)*(px-lot.price);remaining-=n;lot.quantity-=n;if(!lot.quantity)fifo.shift();}}
 }assert.equal(filled,i.filledQuantity);assert.equal(filled,i.quantity);}
assert([...inventory.values()].every(lots=>!lots.length));
const decisions=verified(path.join(rt,'competition','decisions.jsonl'),existing?.sourceProof.officialDecisions.sequence??null);const matched=decisions.rows.map(r=>r.event.decision).filter(d=>d.code==='INTENT_READY').flatMap(d=>intents.filter(i=>i.action==='buy'&&i.marketId===d.marketId&&Math.abs(Date.parse(i.preparedAt)-Date.parse(d.clockAt))<1000).map(i=>({marketId:d.marketId,decisionAt:d.clockAt,sourceBid:d.bid,sourceAsk:d.ask,submittedLimit:i.price,actualFillPrices:[...new Set(i.reconciledFills.map(f=>f.price))]})));
const mechanism=JSON.parse(fs.readFileSync('data/native-mechanisms-future-1791205489070.json')),full=fs.readFileSync(path.join(rt,'research-cohorts',mechanism.protocol.cohort,mechanism.fullOutputName));assert.equal(sha(full),mechanism.fullOutputHash);const native=JSON.parse(full);
const sensitivity=Object.entries(native.markouts.sides).flatMap(([side,s])=>s.strict.cards.map(c=>{const observed=c.episodes.filter(e=>e.status==='observed');const ideal=observed.map(e=>BigInt(e.quotedNetMarkoutMicros)+BigInt(e.slippageCostMicros));return{side,strategy:c.strategy,scenario:c.scenario.id,observed:ideal.length,declaredAdverseTicks:c.scenario.slippageTicks,meanDeclaredStress:c.summary.quotedNetMarkout.mean,meanWithoutAdditionalAdverseTicks:ideal.length?Number(ideal.reduce((n,v)=>n+v,0n))/ideal.length/1e6:null,positiveWithoutAdditionalAdverseTicks:ideal.filter(x=>x>0n).length};}));
const report={schemaVersion:1,at:new Date().toISOString(),claimComment:5996357048,mode:'attributed_fill_cost_and_counterfactual_opportunity_audit',sourceProof:{passive:passive.proof,tape:tape.proof,officialCore:core.proof,officialIntentLedger:{bytes:ledgerBytes.length,sha256:sha(ledgerBytes),sequence:ledger.sequence,tailHash:ledger.lastHash},officialDecisions:decisions.proof,mechanismOutputHash:mechanism.fullOutputHash},
 official:{intents:intents.length,filledOrders:intents.length,fillRecords:actualFills,fillsAtSubmittedLimit:atLimit,priceImprovedFills:priceImproved,nonLimitViolations:0,matchedEntryBookObservations:matched,openAttributedShares:0,recordedPriceGrossRealized:money([...markets.values()].reduce((n,m)=>n+m.realized,0n)),markets:[...markets.values()].map(m=>({marketId:m.marketId,buyShares:m.buyShares,sellShares:m.sellShares,buyCost:money(m.buyCost),sellProceeds:money(m.sellProceeds),recordedPriceGrossRealized:money(m.realized)})),addedFees:0,otherAccountHoldingsAdopted:false},
 passive:{cohort:'baal-stable-spread-20261005-v2-live',bankHash:state.paper.bankHash,quotes:opportunities.length,quotesWithTouches:opportunities.filter(x=>x.touchEvents>0).length,quotesWithStrictThrough:opportunities.filter(x=>x.strictThroughEvents>0).length,unusablePrices:opportunities.reduce((n,x)=>n+x.unusablePrices,0),opportunities,queuePositionProven:false,executionProven:false},
 quoteCostSensitivity:{cases:sensitivity.length,positiveMeanWithoutExtraTicks:sensitivity.filter(x=>x.meanWithoutAdditionalAdverseTicks>0).length,sensitivity},
 limitations:['Actual fills at the submitted limit do not prove zero slippage relative to an earlier book. Only source-linked entry observations can support that comparison.','Recorded-price gross realization excludes unverified non-price deductions; zero added fees is the bot policy.','Removing the declared adverse-tick stress is an optimistic quote sensitivity, not an execution model or demonstrated profit.','Touches and anonymous trade sizes do not establish aggressor, priority or a hypothetical fill.','Cases, scenarios and YES/NO opportunities are correlated; reused data is not new out-of-sample evidence.'],networkRequests:0,competitionOrders:0,persistentServicesAdded:0,profitabilityEstablished:false};
if(verifyExisting){for(const key of ['passive','tape','officialCore','officialDecisions'])assert.deepEqual(report.sourceProof[key],existing.sourceProof[key]);for(const key of ['official','passive','quoteCostSensitivity'])assert.deepEqual(report[key],existing[key]);fs.writeFileSync('data/fill-economics-reproduction-20261005.json',JSON.stringify({schemaVersion:1,at:new Date().toISOString(),reportHash:sha(fs.readFileSync('data/fill-economics-audit-20261005.json')),sourcePrefixProofsExact:true,economicResultsExact:true,officialIntentLedger:report.sourceProof.officialIntentLedger,networkRequests:0,competitionOrders:0,profitabilityEstablished:false},null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({sourcePrefixProofsExact:true,economicResultsExact:true,officialGrossRealized:report.official.recordedPriceGrossRealized,networkRequests:0}));}else{
fs.writeFileSync('data/fill-economics-audit-20261005.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({official:report.official,passive:{quotes:report.passive.quotes,touchQuotes:report.passive.quotesWithTouches,throughQuotes:report.passive.quotesWithStrictThrough,unusable:report.passive.unusablePrices},sensitivity:{cases:sensitivity.length,positiveIdealCases:report.quoteCostSensitivity.positiveMeanWithoutExtraTicks}}));

}
